// lib
namespace ProjectA
{
    // No MessagePack reference and no attributes: the library stays dependency-free.
    public class MyType
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public double Score;
    }
}
// app
using MessagePack;
using MessagePack.Formatters;

namespace ProjectB
{
    // old: CS0246, the attribute does not exist and nothing is generated.
    // new: the generator's extra pipeline input picks this class up and emits
    //      Serialize/Deserialize for ProjectA.MyType (string keys Id, Name, Score).
    [GeneratedMessagePackFormatter]
    public partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType>
    {
    }

    public static class Use
    {
        // Compiles only when the generated half supplies the interface members.
        public static byte[] Pack(ProjectA.MyType value)
        {
            var options = MessagePackSerializerOptions.Standard.WithResolver(
                MessagePack.Resolvers.CompositeResolver.Create(
                    new IMessagePackFormatter[] { new MyTypeFormatter() },
                    new IFormatterResolver[] { MessagePack.Resolvers.StandardResolver.Instance }));
            return MessagePackSerializer.Serialize(value, options);
        }
    }
}
